package br.com.rpl.orcamentos;
import android.content.*;import android.net.Uri;import android.os.Build;import android.provider.MediaStore;import android.util.Base64;import java.io.*;import com.getcapacitor.*;import com.getcapacitor.annotation.CapacitorPlugin;
@CapacitorPlugin(name="RplFiles") public class RplFiles extends Plugin {
 @PluginMethod public void save(PluginCall call){Uri uri=null;try{String name=call.getString("name");if(name==null||!name.matches("[A-Za-z0-9_-]+\\.pdf"))throw new Exception("Nome inválido");byte[] bytes=Base64.decode(call.getString("data"),Base64.DEFAULT);if(Build.VERSION.SDK_INT<29)throw new Exception("Download requer Android 10 ou superior");ContentResolver r=getContext().getContentResolver();ContentValues v=new ContentValues();v.put(MediaStore.MediaColumns.DISPLAY_NAME,name);v.put(MediaStore.MediaColumns.MIME_TYPE,"application/pdf");v.put(MediaStore.MediaColumns.RELATIVE_PATH,"Download/RPL");v.put(MediaStore.MediaColumns.IS_PENDING,1);uri=r.insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,v);if(uri==null)throw new IOException("Falha ao criar arquivo");try(OutputStream out=r.openOutputStream(uri)){if(out==null)throw new IOException("Arquivo indisponível");out.write(bytes);}v.clear();v.put(MediaStore.MediaColumns.IS_PENDING,0);r.update(uri,v,null,null);JSObject result=new JSObject();result.put("uri",uri.toString());call.resolve(result);}catch(Exception e){if(uri!=null)getContext().getContentResolver().delete(uri,null,null);call.reject(e.getMessage());}}
 @PluginMethod public void share(PluginCall call){try{Uri uri=Uri.parse(call.getString("uri"));if(!"content".equals(uri.getScheme()))throw new Exception("Gere novamente este PDF");Intent i=new Intent(Intent.ACTION_SEND);i.setType("application/pdf");i.putExtra(Intent.EXTRA_STREAM,uri);i.setClipData(ClipData.newRawUri("PDF",uri));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);getActivity().runOnUiThread(()->{try{Intent w=new Intent(i).setPackage("com.whatsapp");try{getActivity().startActivity(w);}catch(ActivityNotFoundException e){try{getActivity().startActivity(new Intent(i).setPackage("com.whatsapp.w4b"));}catch(ActivityNotFoundException e2){getActivity().startActivity(Intent.createChooser(i,"Enviar PDF"));}}call.resolve();}catch(Exception e){call.reject(e.getMessage());}});}catch(Exception e){call.reject(e.getMessage());}}
}
